{"command": "cd /root && python3 -c "
import ezdxf
d = ezdxf.readfile('/root/output/repaired_plan.dxf')
counts = {}
for e in d.modelspace():
    L = e.dxf.layer
    counts[L] = counts.get(L, 0) + 1
print('REPAIR-* layer entities:')
for L in sorted(counts):
    if L.startswith('REPAIR'):
        print(f'  {L}: {counts[L]}')
" && rm -f /root/build_outputs.py /root/render_preview.py && ls /root/output/", "summary": "Verify DXF layers and clean up scratch scripts"}

