import ezdxf
doc = ezdxf.readfile('/root/input/ada_bath_input.dxf')
msp = doc.modelspace()

def bbox_of(entity):
    if entity.dxftype() == 'LINE':
        return [entity.dxf.start.x, entity.dxf.start.y, entity.dxf.end.x, entity.dxf.end.y]
    return None

print("=== WALL LINES / POLYLINES ===")
for e in msp.query('*[layer=="WALL"]'):
    if e.dxftype() == 'LINE':
        print(f"LINE  ({e.dxf.start.x:.3f}, {e.dxf.start.y:.3f}) -> ({e.dxf.end.x:.3f}, {e.dxf.end.y:.3f})")
    elif e.dxftype() == 'POLYLINE':
        pts = [(v.dxf.location.x, v.dxf.location.y) for v in e.vertices]
        print(f"POLYLINE ({len(pts)} pts): {[(round(x,2),round(y,2)) for x,y in pts]}")

print("\n=== CLEARANCE ===")
for e in msp.query('*[layer=="CLEARANCE"]'):
    if e.dxftype() == 'CIRCLE':
        print(f"CIRCLE center=({e.dxf.center.x:.3f},{e.dxf.center.y:.3f}) r={e.dxf.radius:.3f}")
    elif e.dxftype() == 'POLYLINE':
        pts = [(v.dxf.location.x, v.dxf.location.y) for v in e.vertices]
        print(f"POLYLINE ({len(pts)} pts): {[(round(x,2),round(y,2)) for x,y in pts]}")
