import ezdxf
from math import cos, sin, radians
doc = ezdxf.readfile('/root/input/ada_bath_input.dxf')
msp = doc.modelspace()

def entity_extents(e):
    """Get bbox of an entity by sampling."""
    t = e.dxftype()
    pts = []
    if t == 'LINE':
        pts = [(e.dxf.start.x, e.dxf.start.y), (e.dxf.end.x, e.dxf.end.y)]
    elif t == 'CIRCLE':
        c = e.dxf.center; r = e.dxf.radius
        for a in range(0, 360, 15):
            pts.append((c.x + r*cos(radians(a)), c.y + r*sin(radians(a))))
    elif t == 'ARC':
        c = e.dxf.center; r = e.dxf.radius
        s, ee = e.dxf.start_angle, e.dxf.end_angle
        if ee < s: ee += 360
        a = s
        while a <= ee:
            pts.append((c.x + r*cos(radians(a)), c.y + r*sin(radians(a))))
            a += 5
        pts.append((c.x + r*cos(radians(ee)), c.y + r*sin(radians(ee))))
    elif t == 'POLYLINE':
        pts = [(v.dxf.location.x, v.dxf.location.y) for v in e.vertices]
    elif t == 'LWPOLYLINE':
        pts = [(p[0], p[1]) for p in e.get_points()]
    elif t == 'SPLINE':
        try:
            for p in e.control_points:
                pts.append((p[0], p[1]))
            # also sample the spline
            from ezdxf.math import Vec3
            for p in e.flattening(0.1):
                pts.append((p.x, p.y))
        except Exception as ex:
            pass
    return pts

def summarize(layer, radius_filter=None):
    xs, ys = [], []
    ent_ext = []
    for e in msp.query(f'*[layer=="{layer}"]'):
        pts = entity_extents(e)
        if pts:
            exs = [p[0] for p in pts]; eys=[p[1] for p in pts]
            ent_ext.append((e.dxftype(), min(exs), min(eys), max(exs), max(eys), getattr(e.dxf, 'radius', None)))
            xs += exs; ys += eys
    if xs:
        print(f"{layer}: overall bbox ({min(xs):.3f}, {min(ys):.3f}) -> ({max(xs):.3f}, {max(ys):.3f})")
    return ent_ext

for L in ['FIXTURE-WC', 'FIXTURE-LAV', 'FIXT-TUB', 'GRABRAIL', 'DOOR']:
    print(f"\n=== {L} ===")
    ext = summarize(L)
    # Filter for outliers - big radii
    for row in ext:
        if row[5] is not None and row[5] > 20:
            print(f"  large radius arc/circle: {row}")

